import json,concurrent.futures as cf
from exa_clients import exa
Q={
"pumps_valves":["pump manufacturer online catalog with thousands of models and part numbers sold through distributors","valve manufacturer product catalog with over 10,000 part numbers and distributor portal","industrial valve manufacturer configurable products CAD downloads online catalog","metering and dosing pump manufacturer catalog of models with configuration options","check valves ball valves manufacturer catalog hundreds of variants by size and material","sanitary and hygienic pump and valve manufacturer catalog configurator","diaphragm and gear pump manufacturer catalog dealer portal","pressure regulators and control valves manufacturer online catalog"],
"hydraulics_fluid":["hydraulic fittings hoses adapters manufacturer online catalog thousands of part numbers","hydraulic cylinders manufacturer catalog standard and custom variants distributor portal","pneumatic components manufacturer catalog 10,000 products distributors","quick disconnect couplings manufacturer catalog part numbers","fluid power components manufacturer configurator online catalog","industrial hose and fittings manufacturer catalog sold through distributors","filtration elements manufacturer catalog cross reference part numbers","manifolds and hydraulic valves manufacturer catalog cartridge valves"],
"fasteners_components":["fastener manufacturer online catalog 100,000 SKUs bolts screws nuts washers","stainless steel fasteners manufacturer catalog part numbers distributor","precision turned components manufacturer standard parts catalog","springs manufacturer catalog standard stock springs thousands of sizes","plugs caps and protective closures manufacturer catalog thousands of part numbers","rivets inserts and anchors manufacturer catalog technical data","o-rings seals gaskets manufacturer catalog standard sizes","clamps hardware and standoffs manufacturer catalog hundreds of variants","retaining rings pins and shims manufacturer catalog standard parts","electrical connectors and terminals manufacturer catalog part numbers"],
"power_transmission":["bearings manufacturer online catalog thousands of part numbers distributors","gears gearboxes manufacturer catalog standard stock gears configurator","roller chain sprockets manufacturer catalog part numbers","couplings clutches and brakes manufacturer catalog sizes configurator","belts and pulleys manufacturer catalog part numbers distributor","linear motion components manufacturer catalog configurable","shaft collars and mechanical power transmission manufacturer catalog","gear motors and speed reducers manufacturer configurator catalog"],
"tools":["industrial hand tools manufacturer catalog thousands of items distributor","cutting tools manufacturer catalog end mills drills inserts part numbers","abrasives manufacturer catalog grit sizes product variants distributors","power tool accessories manufacturer catalog hundreds of products","measuring and workholding tools manufacturer catalog part numbers","torque tools wrenches sockets manufacturer catalog thousands of SKUs","welding consumables and accessories manufacturer catalog distributors","industrial vacuum and blast equipment manufacturer parts catalog"],
"electrical_automation":["industrial relays contactors manufacturer catalog thousands of models","sensors and switches manufacturer online catalog configure by part number","enclosures manufacturer catalog standard sizes configurator","terminal blocks and connectors manufacturer catalog 10,000 part numbers","cable assemblies and cordsets manufacturer catalog variants","industrial controls and automation components manufacturer catalog distributors","circuit protection fuses manufacturer catalog part numbers","motors and variable frequency drives manufacturer catalog configurator","industrial lighting and electrical components manufacturer catalog large product range","limit switches encoders manufacturer catalog configurable options"],
"general":["manufacturer product catalog image coming soon placeholder","industrial parts catalog with thousands of SKUs sold through distributors only line drawings","manufacturer web catalog 50,000 products CAD models downloads","distributor portal for industrial manufacturer catalog part number lookup","manufacturer catalog with product families and variants configure part number","high volume consumable industrial parts manufacturer catalog"]}
def job(a):
    v,qq,cat=a; b={"query":qq,"numResults":100,"type":"auto"}
    if cat: b["category"]="company"
    r=exa(b)
    return {"vert":v,"query":qq,"cat":cat,"err":r.get("error"),"cost":(r.get("costDollars") or {}).get("total",0),"results":[{"url":x.get("url"),"title":x.get("title")} for x in r.get("results",[])]}
args=[(v,qq,c) for v,qs in Q.items() for qq in qs for c in (True,False)]
with cf.ThreadPoolExecutor(6) as ex: out=list(ex.map(job,args))
json.dump(out,open("exa_lt.json","w"))
print(len(out),"queries; results",sum(len(o["results"]) for o in out),"cost",round(sum(o["cost"] for o in out),2),"errors",sum(1 for o in out if o["err"]))
